@layer components {
  :where([data-control-family="range"][data-range-kind="slider"][data-slot="label-overlay"]) {
    padding-inline: calc(var(--spacing) * 3);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="track"]) {
    --_range-track-background: var(--cui-range-track-background);
    block-size: var(--cui-range-track-size);
    border-radius: var(--cui-range-track-radius);
    background: var(--_range-track-background);
    touch-action: pan-y;
    transition: background-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="track"][data-dragging]) {
    --_range-track-background: var(--cui-range-track-dragging-background);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="indicator"]) {
    --_range-indicator-background: var(--cui-range-indicator-background);
    block-size: 100%;
    border-radius: var(--cui-range-indicator-radius);
    background: var(--_range-indicator-background);
    transition: background-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="indicator"][data-dragging]) {
    --_range-indicator-background: var(--cui-range-indicator-dragging-background);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="control"]) {
    padding-block: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="control"][data-labeled]) {
    block-size: calc(var(--spacing) * 7.5);
    padding-block: 0;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="track"][data-labeled]) {
    block-size: 100%;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"]) {
    --_range-thumb-background: var(--cui-range-thumb-background);
    --_range-thumb-shadow: var(--cui-range-thumb-shadow);
    position: relative;
    inline-size: var(--cui-range-thumb-inline-size);
    block-size: var(--cui-range-thumb-block-size);
    border: var(--_range-thumb-border-width) solid var(--cui-range-thumb-border-color);
    border-radius: var(--cui-range-thumb-radius);
    background: var(--_range-thumb-background);
    box-shadow: var(--_range-thumb-shadow);
    touch-action: pan-y;
    transition-property: scale, box-shadow, block-size, inline-size;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) {
    :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"]:hover:not([data-disabled])) {
      --_range-thumb-background: var(--cui-range-thumb-hover-background);
      scale: 1.1;
    }

    :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"][data-variant="plain"]:hover:not([data-disabled])) {
      scale: 1;
    }
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"][data-dragging]) {
    --_range-thumb-background: var(--cui-range-thumb-dragging-background);
    --_range-thumb-shadow: var(--cui-range-thumb-dragging-shadow);
    scale: 1.1;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"][data-variant="plain"][data-dragging]) {
    block-size: calc(var(--cui-range-thumb-block-size) * 1.25);
    scale: 1;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="tick"]) {
    inline-size: 1px;
    block-size: var(--cui-range-track-size);
    background: oklch(from var(--foreground) l c h / 0.15);
    transition-property: block-size, background-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"][data-dragging] [data-slot="tick"]) {
    block-size: calc(var(--cui-range-track-size) * 2);
    background: oklch(from var(--foreground) l c h / 0.25);
  }

  :where([data-control-family="range"][data-range-kind="slider"]:is([data-slot="label"], [data-slot="value"])) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
    line-height: var(--leading-tight);
    letter-spacing: var(--tracking-tight);
    transition-property: color, scale, translate;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="value"]) {
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"][data-dragging] [data-slot="label"]) {
    translate: calc(var(--spacing) * -1) calc(var(--spacing) * -1.5);
    scale: 0.9;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"][data-dragging] [data-slot="value"]) {
    translate: calc(var(--spacing) * 0.5) calc(var(--spacing) * -1.5);
    color: var(--foreground);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="control"]) {
    padding-inline: calc(var(--spacing) * 1.5);
    padding-block: 0;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="control"][data-labeled]) {
    inline-size: calc(var(--spacing) * 7.5);
    block-size: auto;
    padding-inline: 0;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="track"]),
  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="thumb"]) {
    touch-action: pan-x;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="track"]) {
    inline-size: var(--cui-range-track-size);
    block-size: auto;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="track"][data-labeled]) {
    inline-size: 100%;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="indicator"]) {
    inline-size: 100%;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="thumb"][data-variant="plain"]) {
    inline-size: var(--cui-range-thumb-block-size);
    block-size: var(--cui-range-thumb-inline-size);
  }

  :where(
    [data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="thumb"][data-variant="plain"][data-dragging]
  ) {
    inline-size: calc(var(--cui-range-thumb-block-size) * 1.25);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="root"] [data-slot="tick"]) {
    inline-size: var(--cui-range-track-size);
    block-size: 1px;
    inset-inline-start: 0;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="root"] [data-slot="label"]) {
    margin-block-end: calc(var(--spacing) * 1.5);
    translate: none;
    scale: none;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-orientation="vertical"][data-slot="root"] [data-slot="value"]) {
    margin-block-start: calc(var(--spacing) * 1.5);
    translate: none;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"])::after {
    content: "";
    position: absolute;
    inset: 50% auto auto 50%;
    translate: -50% -50%;
    inline-size: max(100%, var(--target-min));
    block-size: max(100%, var(--target-min));
  }

  @media (pointer: coarse) {
    :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"])::after {
      inline-size: max(100%, var(--touch-target));
      block-size: max(100%, var(--touch-target));
    }
  }

  @media (forced-colors: active) {
    :where([data-control-family="range"][data-range-kind="slider"][data-slot="indicator"]) {
      background: Highlight;
    }

    :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"][data-variant="plain"]) {
      background: CanvasText;
    }
  }
}

@layer components {
  :where([data-control-family="range"][data-slot="root"]) {
    --cui-range-track-radius: 9999px;
    --cui-range-track-size: calc(var(--spacing) * 2);
    --cui-range-track-background: var(--muted);
    --cui-range-indicator-radius: 9999px;
    --cui-range-indicator-background: var(--primary);
    --cui-range-thumb-radius: 9999px;
    --cui-range-thumb-inline-size: calc(var(--spacing) * 3.5);
    --cui-range-thumb-block-size: calc(var(--spacing) * 3.5);
    --cui-range-thumb-background: var(--background);
    --cui-range-thumb-border-color: var(--control-rim);
    --cui-range-thumb-shadow: var(--shadow-sm);
    --cui-range-indeterminate-size: 40%;
    --cui-range-indeterminate-animation-duration: calc(var(--duration-loop) * 1.5);
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"]) {
    --cui-range-track-size: calc(var(--spacing) * 1.5);
    --cui-range-track-dragging-background: var(--active-fill);
    --cui-range-indicator-dragging-background: var(--primary);
    --cui-range-thumb-hover-background: var(--cui-range-thumb-background);
    --cui-range-thumb-dragging-background: var(--cui-range-thumb-background);
    --cui-range-thumb-dragging-shadow: var(--shadow-md);
    --_range-thumb-border-width: var(--control-rim-width);
    cursor: pointer;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"][data-variant="plain"]) {
    --cui-range-track-radius: min(var(--radius-sm), 3px);
    --cui-range-track-background: var(--hover-fill);
    --cui-range-indicator-radius: var(--cui-range-track-radius);
    --cui-range-indicator-background: oklch(from var(--foreground) l c h / 0.14);
    --cui-range-thumb-radius: min(var(--radius-sm), 1px);
    --cui-range-thumb-inline-size: 0.125rem;
    --cui-range-thumb-block-size: 1rem;
    --cui-range-thumb-background: oklch(from var(--foreground) l c h / 0.3);
    --cui-range-thumb-hover-background: oklch(from var(--foreground) l c h / 0.5);
    --cui-range-thumb-dragging-background: oklch(from var(--foreground) l c h / 0.7);
    --cui-range-thumb-shadow: 0 0 transparent;
    --_range-thumb-border-width: 0px;
  }

  :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"][data-disabled]) {
    opacity: var(--disabled-opacity);
    cursor: not-allowed;
  }

  :where([data-control-family="range"][data-range-kind="progress"][data-slot="root"]),
  :where([data-control-family="range"][data-range-kind="meter"][data-slot="root"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="range"][data-range-kind="progress"][data-slot="track"]),
  :where([data-control-family="range"][data-range-kind="meter"][data-slot="track"]) {
    block-size: var(--cui-range-track-size);
    border-radius: var(--cui-range-track-radius);
    background: var(--cui-range-track-background);
  }

  :where([data-control-family="range"][data-range-kind="progress"][data-slot="indicator"]),
  :where([data-control-family="range"][data-range-kind="meter"][data-slot="indicator"]) {
    block-size: 100%;
    border-radius: var(--cui-range-indicator-radius);
    background: var(--cui-range-indicator-background);
  }

  :where([data-control-family="range"][data-range-kind="progress"][data-slot="indicator"]) {
    transition-property: width;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="range"][data-range-kind="progress"][data-slot="indicator"][data-indeterminate]) {
    inline-size: var(--cui-range-indeterminate-size);
    animation: cui-range-indeterminate var(--cui-range-indeterminate-animation-duration) var(--ease-standard) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    :where([data-control-family="range"][data-range-kind="progress"][data-slot="indicator"][data-indeterminate]) {
      animation: none;
      opacity: 0.6;
    }
  }

  :where([data-motion="reduced"] [data-control-family="range"][data-range-kind="progress"][data-slot="indicator"][data-indeterminate]) {
    animation: none;
    opacity: 0.6;
  }

  :where([data-control-family="range"][data-range-kind="progress"][data-slot="value"]) {
    font-size: var(--text-label);
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="range"][data-range-kind="progress"][data-slot="label"]) {
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
    color: var(--foreground);
  }

  :where([data-control-family="range"][data-range-kind="meter"][data-slot="indicator"]) {
    transition-property: width;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="range"][data-range-kind="meter"][data-slot="value"]) {
    font-size: var(--text-label);
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="range"][data-range-kind="meter"][data-slot="label"]) {
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
    color: var(--foreground);
  }

  @media (forced-colors: active) {
    :where([data-control-family="range"][data-slot="track"]) {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }

    :where([data-control-family="range"][data-slot="indicator"]) {
      background: Highlight;
    }
  }

  @keyframes cui-range-indeterminate {
    from {
      margin-inline-start: calc(var(--cui-range-indeterminate-size) * -1);
    }
    to {
      margin-inline-start: 100%;
    }
  }
}

